"use client";

import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalEditor,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  SerializedLexicalNode,
  Spread,
} from "lexical";
import { DecoratorNode } from "lexical";
import type { JSX } from "react";

import { ExcalidrawComponent } from "../../../plugins/excalidraw/component";

export type ExcalidrawDimension = number | "inherit";

export type ExcalidrawAlignment = "left" | "center" | "right";

export type SerializedExcalidrawNode = Spread<
  {
    alignment?: ExcalidrawAlignment;
    data: string;
    height?: ExcalidrawDimension;
    width?: ExcalidrawDimension;
  },
  SerializedLexicalNode
>;

/** Attribute used for HTML round-trips of excalidraw scenes. */
export const EXCALIDRAW_DATA_ATTRIBUTE = "data-lexical-excalidraw-json";

const getExcalidrawAlignment = (domNode: HTMLElement): ExcalidrawAlignment => {
  const { marginLeft, marginRight } = domNode.style;

  if (marginLeft === "auto" && marginRight === "auto") {
    return "center";
  }

  if (marginLeft === "auto") {
    return "right";
  }

  return "left";
};

const parsePixelDimension = (value: string): ExcalidrawDimension => {
  const normalized = value.trim().replace(/px$/iu, "");
  if (!normalized) {
    return "inherit";
  }
  const parsed = Number(normalized);
  return Number.isFinite(parsed) && parsed > 0 ? Math.round(parsed) : "inherit";
};

const convertExcalidrawElement = (
  domNode: HTMLElement
): DOMConversionOutput | null => {
  const data = domNode.getAttribute(EXCALIDRAW_DATA_ATTRIBUTE);
  if (!data) {
    return null;
  }

  return {
    node: $createExcalidrawNode({
      alignment: getExcalidrawAlignment(domNode),
      data,
      height: parsePixelDimension(domNode.style.height),
      width: parsePixelDimension(domNode.style.width),
    }),
  };
};

export interface ExcalidrawNodePayload {
  alignment?: ExcalidrawAlignment;
  data?: string;
  height?: ExcalidrawDimension;
  key?: NodeKey;
  width?: ExcalidrawDimension;
}

/**
 * Block-level decorator node that stores an excalidraw scene as serialized
 * JSON. The rendered drawing is embedded into `exportDOM` alongside the raw
 * data attribute so pasted HTML stays visible outside the editor and can be
 * re-imported as an editable drawing.
 */
export class ExcalidrawNode extends DecoratorNode<JSX.Element> {
  __alignment: ExcalidrawAlignment;
  __data: string;
  __height: ExcalidrawDimension;
  __width: ExcalidrawDimension;

  constructor(
    data = "[]",
    alignment: ExcalidrawAlignment = "left",
    width: ExcalidrawDimension = "inherit",
    height: ExcalidrawDimension = "inherit",
    key?: NodeKey
  ) {
    super(key);
    this.__data = data;
    this.__alignment = alignment;
    this.__width = width;
    this.__height = height;
  }

  static getType(): string {
    return "excalidraw";
  }

  static clone(node: ExcalidrawNode): ExcalidrawNode {
    return new ExcalidrawNode(
      node.__data,
      node.__alignment,
      node.__width,
      node.__height,
      node.__key
    );
  }

  static importDOM(): DOMConversionMap | null {
    return {
      span: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute(EXCALIDRAW_DATA_ATTRIBUTE)) {
          return null;
        }

        return {
          conversion: convertExcalidrawElement,
          priority: 1,
        };
      },
    };
  }

  static importJSON(serializedNode: SerializedExcalidrawNode): ExcalidrawNode {
    return $createExcalidrawNode({
      alignment: serializedNode.alignment,
      data: serializedNode.data,
      height: serializedNode.height,
      width: serializedNode.width,
    }).updateFromJSON(serializedNode);
  }

  updateFromJSON(
    serializedNode: LexicalUpdateJSON<SerializedExcalidrawNode>
  ): this {
    return super
      .updateFromJSON(serializedNode)
      .setData(serializedNode.data ?? "[]")
      .setAlignment(serializedNode.alignment ?? "left")
      .setHeight(serializedNode.height ?? "inherit")
      .setWidth(serializedNode.width ?? "inherit");
  }

  exportJSON(): SerializedExcalidrawNode {
    return {
      ...super.exportJSON(),
      alignment: this.__alignment,
      data: this.__data,
      height: this.__height === "inherit" ? undefined : this.__height,
      type: "excalidraw",
      version: 1,
      width: this.__width === "inherit" ? undefined : this.__width,
    };
  }

  exportDOM(editor: LexicalEditor): DOMExportOutput {
    const element = document.createElement("span");
    element.style.display = "block";

    // Mirror ImageNode's export so both block types round-trip alignment.
    if (this.__alignment === "center") {
      element.style.marginLeft = "auto";
      element.style.marginRight = "auto";
    } else if (this.__alignment === "right") {
      element.style.marginLeft = "auto";
      element.style.marginRight = "0";
    }

    // Embed the currently rendered svg so exported/pasted HTML shows the
    // drawing even where excalidraw is unavailable.
    const content = editor.getElementByKey(this.getKey());
    const svg = content?.querySelector("svg");
    if (svg) {
      element.append(svg.cloneNode(true));
    }

    if (this.__width !== "inherit") {
      element.style.width = `${this.__width}px`;
    }

    if (this.__height !== "inherit") {
      element.style.height = `${this.__height}px`;
    }

    element.setAttribute(EXCALIDRAW_DATA_ATTRIBUTE, this.__data);
    return { element };
  }

  createDOM(config: EditorConfig): HTMLElement {
    const span = document.createElement("span");

    if (typeof config.theme.image === "string") {
      addClassNamesToElement(span, config.theme.image);
    }

    return span;
  }

  updateDOM(): false {
    return false;
  }

  decorate(): JSX.Element {
    return (
      <ExcalidrawComponent
        alignment={this.__alignment}
        data={this.__data}
        height={this.__height}
        nodeKey={this.getKey()}
        width={this.__width}
      />
    );
  }

  isInline(): false {
    return false;
  }

  getData(): string {
    return this.getLatest().__data;
  }

  getAlignment(): ExcalidrawAlignment {
    return this.getLatest().__alignment;
  }

  getWidth(): ExcalidrawDimension {
    return this.getLatest().__width;
  }

  getHeight(): ExcalidrawDimension {
    return this.getLatest().__height;
  }

  setData(data: string): this {
    const writable = this.getWritable();
    writable.__data = data;
    return writable;
  }

  setAlignment(alignment: ExcalidrawAlignment): this {
    const writable = this.getWritable();
    writable.__alignment = alignment;
    return writable;
  }

  setWidth(width: ExcalidrawDimension): this {
    const writable = this.getWritable();
    writable.__width = width;
    return writable;
  }

  setHeight(height: ExcalidrawDimension): this {
    const writable = this.getWritable();
    writable.__height = height;
    return writable;
  }
}

export function $createExcalidrawNode({
  alignment,
  data,
  height,
  key,
  width,
}: ExcalidrawNodePayload = {}): ExcalidrawNode {
  return new ExcalidrawNode(data, alignment, width, height, key);
}

export function $isExcalidrawNode(
  node: LexicalNode | null | undefined
): node is ExcalidrawNode {
  return node instanceof ExcalidrawNode;
}

"use client";

import { createCommand } from "lexical";
import type { LexicalCommand } from "lexical";

export const INSERT_EXCALIDRAW_COMMAND: LexicalCommand<void> = createCommand(
  "INSERT_EXCALIDRAW_COMMAND"
);

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { useLexicalNodeSelection } from "@lexical/react/useLexicalNodeSelection";
import { mergeRegister } from "@lexical/utils";
import {
  $getNodeByKey,
  $getSelection,
  $isNodeSelection,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  DRAGSTART_COMMAND,
  FORMAT_ELEMENT_COMMAND,
  KEY_BACKSPACE_COMMAND,
  KEY_DELETE_COMMAND,
} from "lexical";
import type { LexicalEditor, NodeKey } from "lexical";
import { PencilIcon } from "lucide-react";
import type { RefObject } from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { $isExcalidrawNode } from "../../core/nodes/excalidraw/node";
import type { ExcalidrawAlignment } from "../../core/nodes/excalidraw/node";
import { ImageResizer } from "../image/resizer";
import { ExcalidrawImage } from "./image";
import { ExcalidrawEditorDialog } from "./modal";
import type { SaveExcalidrawScenePayload } from "./modal";
import {
  hasExcalidrawContent,
  parseExcalidrawScene,
  serializeExcalidrawScene,
} from "./scene";

interface ExcalidrawComponentProps {
  alignment: ExcalidrawAlignment;
  data: string;
  height: number | "inherit";
  nodeKey: NodeKey;
  width: number | "inherit";
}

interface SelectionBehaviorOptions {
  buttonRef: RefObject<HTMLButtonElement | null>;
  clearSelection: () => void;
  editable: boolean;
  isNodeSelected: boolean;
  isResizing: boolean;
  nodeKey: NodeKey;
  openEditor: () => void;
  removeNode: () => void;
  setSelected: (selected: boolean) => void;
}

const isInsideButton = (
  button: HTMLButtonElement | null,
  target: EventTarget | null
): boolean =>
  Boolean(button && target instanceof Node && button.contains(target));

const useExcalidrawSelectionBehavior = ({
  buttonRef,
  clearSelection,
  editable,
  isNodeSelected,
  isResizing,
  nodeKey,
  openEditor,
  removeNode,
  setSelected,
}: SelectionBehaviorOptions) => {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    if (!editable) {
      if (isNodeSelected) {
        clearSelection();
      }
      return;
    }

    const removeSelectedDrawing = (event: KeyboardEvent) => {
      if (!isNodeSelected) {
        return false;
      }

      event.preventDefault();
      removeNode();
      return true;
    };

    return mergeRegister(
      editor.registerCommand(
        CLICK_COMMAND,
        (event) => {
          if (isResizing) {
            return true;
          }

          if (!isInsideButton(buttonRef.current, event.target)) {
            return false;
          }

          if (event.shiftKey) {
            setSelected(!isNodeSelected);
          } else {
            clearSelection();
            setSelected(true);
          }

          if (event.detail > 1) {
            openEditor();
          }

          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        DRAGSTART_COMMAND,
        (event) => {
          if (!isInsideButton(buttonRef.current, event.target)) {
            return false;
          }

          event.preventDefault();
          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        FORMAT_ELEMENT_COMMAND,
        (format) => {
          if (!isNodeSelected) {
            return false;
          }

          if (
            !(format === "left" || format === "center" || format === "right")
          ) {
            return false;
          }

          editor.update(() => {
            const node = $getNodeByKey(nodeKey);
            if ($isExcalidrawNode(node)) {
              node.setAlignment(format as ExcalidrawAlignment);
            }
          });

          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_BACKSPACE_COMMAND,
        removeSelectedDrawing,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_DELETE_COMMAND,
        removeSelectedDrawing,
        COMMAND_PRIORITY_LOW
      )
    );
  }, [
    buttonRef,
    clearSelection,
    editable,
    editor,
    isNodeSelected,
    isResizing,
    nodeKey,
    openEditor,
    removeNode,
    setSelected,
  ]);
};

const applyDimensions = (
  editor: LexicalEditor,
  nodeKey: NodeKey,
  nextWidth: number | "inherit",
  nextHeight: number | "inherit"
) => {
  editor.update(() => {
    const node = $getNodeByKey(nodeKey);
    if ($isExcalidrawNode(node)) {
      node.setWidth(nextWidth);
      node.setHeight(nextHeight);
    }
  });
};

interface ExcalidrawPreviewProps {
  alignment: ExcalidrawAlignment;
  buttonRef: RefObject<HTMLButtonElement | null>;
  containerRef: RefObject<HTMLDivElement | null>;
  editable: boolean;
  editor: LexicalEditor;
  height: number | "inherit";
  isFocused: boolean;
  nodeKey: NodeKey;
  onResizeEnd: (nextWidth: number, nextHeight: number) => void;
  onResizeStart: () => void;
  openEditor: () => void;
  scene: ReturnType<typeof parseExcalidrawScene>;
  width: number | "inherit";
}

function ExcalidrawPreview({
  alignment,
  buttonRef,
  containerRef,
  editable,
  editor,
  height,
  isFocused,
  nodeKey: _nodeKey,
  onResizeEnd,
  onResizeStart,
  openEditor,
  scene,
  width,
}: ExcalidrawPreviewProps) {
  let figureClassName = "my-4 w-fit max-w-full";
  let alignmentClassName = "inline-flex max-w-full";

  if (alignment === "center") {
    figureClassName = "my-4 w-full";
    alignmentClassName = "flex max-w-full justify-center";
  } else if (alignment === "right") {
    figureClassName = "my-4 ml-auto w-fit max-w-full";
    alignmentClassName = "flex max-w-full justify-end";
  }

  const imageElement = (
    <ExcalidrawImage
      appState={scene.appState}
      containerRef={containerRef}
      elements={scene.elements}
      files={scene.files}
      height={height}
      width={width}
    />
  );

  return (
    <figure className={figureClassName}>
      <div className={alignmentClassName}>
        <div className="relative inline-flex max-w-full">
          <div
            className={
              isFocused
                ? "rounded-md ring-1 ring-primary/40 ring-offset-2 ring-offset-background"
                : "rounded-md"
            }
          >
            {editable ? (
              <button
                aria-label="Drawing preview, press Enter or double-click to edit"
                className="block cursor-default overflow-hidden rounded-md border border-border/60 bg-muted/20 shadow-xs focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    openEditor();
                  }
                }}
                ref={buttonRef}
                type="button"
              >
                {imageElement}
              </button>
            ) : (
              <div className="block overflow-hidden rounded-md border border-border/60 bg-muted/20 shadow-xs">
                {imageElement}
              </div>
            )}
          </div>

          {isFocused ? (
            <ImageResizer
              decorations={
                <button
                  aria-label="Edit drawing"
                  className="absolute -top-3 right-2 z-10 flex size-6 items-center justify-center rounded-md bg-popover shadow-lg ring-1 ring-border transition-colors hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                  onClick={(event) => {
                    event.stopPropagation();
                    openEditor();
                  }}
                  onMouseDown={(event) => {
                    event.preventDefault();
                  }}
                  type="button"
                >
                  <PencilIcon
                    aria-hidden
                    className="size-3 text-muted-foreground"
                  />
                </button>
              }
              edgeHandles
              editor={editor}
              imageRef={containerRef}
              onResizeEnd={onResizeEnd}
              onResizeStart={onResizeStart}
            />
          ) : null}
        </div>
      </div>
    </figure>
  );
}

export function ExcalidrawComponent({
  alignment,
  data,
  height,
  nodeKey,
  width,
}: ExcalidrawComponentProps) {
  const [editor] = useLexicalComposerContext();
  const editable = useLexicalEditable();
  const [, setSelected, clearSelection] = useLexicalNodeSelection(nodeKey);
  const [isResizing, setIsResizing] = useState(false);
  const [isNodeSelected, setIsNodeSelected] = useState(() =>
    editor.getEditorState().read(() => {
      const selection = $getSelection();
      return $isNodeSelection(selection) && selection.has(nodeKey);
    })
  );

  useEffect(() => {
    const syncNodeSelection = () => {
      editor.getEditorState().read(() => {
        const selection = $getSelection();
        setIsNodeSelected(
          $isNodeSelection(selection) && selection.has(nodeKey)
        );
      });
    };

    syncNodeSelection();
    return editor.registerUpdateListener(syncNodeSelection);
  }, [editor, nodeKey]);

  const scene = useMemo(() => parseExcalidrawScene(data), [data]);
  const hasContent = hasExcalidrawContent(scene);
  const [isEditorOpen, setIsEditorOpen] = useState(
    () => !hasContent && editable
  );
  const wasEmptyOnMountRef = useRef(!hasContent);
  const resizeEndTimeoutRef = useRef<number | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);

  const removeNode = useCallback(
    () =>
      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if ($isExcalidrawNode(node)) {
          node.remove();
        }
      }),
    [editor, nodeKey]
  );

  const openEditor = useCallback(() => {
    setIsEditorOpen(true);
  }, []);

  useExcalidrawSelectionBehavior({
    buttonRef,
    clearSelection,
    editable,
    isNodeSelected,
    isResizing,
    nodeKey,
    openEditor,
    removeNode,
    setSelected,
  });

  useEffect(
    () => () => {
      if (resizeEndTimeoutRef.current !== null) {
        window.clearTimeout(resizeEndTimeoutRef.current);
        resizeEndTimeoutRef.current = null;
      }
      editor.getRootElement()?.style.removeProperty("cursor");
      document.body.style.removeProperty("cursor");
      document.body.style.removeProperty("-webkit-user-select");
      document.body.style.removeProperty("user-select");
    },
    [editor]
  );

  if (!editable && !hasContent) {
    return null;
  }

  const isFocused = (isNodeSelected || isResizing) && editable;

  const restoreEditorFocus = () => {
    requestAnimationFrame(() => {
      editor.getRootElement()?.focus({ preventScroll: true });
    });
  };

  const handleCloseEditor = () => {
    setIsEditorOpen(false);

    if (wasEmptyOnMountRef.current && !hasContent) {
      removeNode();
    }

    restoreEditorFocus();
  };

  const handleSaveEditor = (payload: SaveExcalidrawScenePayload) => {
    const { appState, elements, files } = payload;
    setIsEditorOpen(false);

    editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if (!$isExcalidrawNode(node)) {
        return;
      }

      if (hasExcalidrawContent({ elements, files })) {
        node.setData(serializeExcalidrawScene(elements, appState, files));
        return;
      }

      node.remove();
    });

    restoreEditorFocus();
  };

  const handleResizeEnd = (nextWidth: number, nextHeight: number) => {
    if (resizeEndTimeoutRef.current !== null) {
      window.clearTimeout(resizeEndTimeoutRef.current);
    }
    resizeEndTimeoutRef.current = window.setTimeout(() => {
      resizeEndTimeoutRef.current = null;
      setIsResizing(false);
    }, 200);

    applyDimensions(editor, nodeKey, nextWidth, nextHeight);
  };

  return (
    <>
      {isEditorOpen ? (
        <ExcalidrawEditorDialog
          initialScene={scene}
          onClose={handleCloseEditor}
          onSave={handleSaveEditor}
        />
      ) : null}

      {hasContent ? (
        <ExcalidrawPreview
          alignment={alignment}
          buttonRef={buttonRef}
          containerRef={containerRef}
          editable={editable}
          editor={editor}
          height={height}
          isFocused={isFocused}
          nodeKey={nodeKey}
          onResizeEnd={handleResizeEnd}
          onResizeStart={() => setIsResizing(true)}
          openEditor={openEditor}
          scene={scene}
          width={width}
        />
      ) : null}
    </>
  );
}

import { $createParagraphNode } from "lexical";
import type { ElementNode } from "lexical";
import { PencilRulerIcon } from "lucide-react";

import {
  $createExcalidrawNode,
  ExcalidrawNode,
} from "../../core/nodes/excalidraw/node";
import type { ExtraEditorFeature } from "../../core/types";
import { replaceCurrentBlock } from "../slash-command/utils";
import { ExcalidrawPlugin } from "./plugin";

// Replacing the selected paragraph leaves the selection dangling, which rolls
// the whole update back — re-anchor it on a trailing paragraph. The empty
// drawing block opens its editing surface as soon as it renders; discarding
// removes the node and keeps the paragraph.
const applyExcalidrawCommand = (targetElement: ElementNode): void => {
  const excalidrawNode = $createExcalidrawNode();
  const paragraph = $createParagraphNode();

  targetElement.replace(excalidrawNode);
  excalidrawNode.insertAfter(paragraph);
  paragraph.select();
};

/**
 * Installs the drawing feature: the `ExcalidrawNode`, its editing surface and
 * the shared insert-menu entry. Ships as the `editor-excalidraw` registry
 * item and pulls `@excalidraw/excalidraw`.
 */
export const excalidrawFeature: ExtraEditorFeature = {
  id: "excalidraw",
  nodes: [ExcalidrawNode],
  plugin: ExcalidrawPlugin,
  slashCommands: [
    {
      command: {
        description: "Draw a diagram or sketch",
        icon: PencilRulerIcon,
        id: "excalidraw",
        keywords: ["drawing", "diagram", "sketch", "whiteboard", "canvas"],
        label: "Drawing",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyExcalidrawCommand);
      },
    },
  ],
};

"use client";

import type {
  ExcalidrawElement,
  NonDeleted,
} from "@excalidraw/excalidraw/element/types";
import type { AppState, BinaryFiles } from "@excalidraw/excalidraw/types";
import { useEffect, useRef, useState } from "react";

interface ExcalidrawImageProps {
  appState?: Partial<AppState>;
  containerRef?: { current: HTMLDivElement | null };
  elements: readonly NonDeleted<ExcalidrawElement>[];
  files?: BinaryFiles;
  height: number | "inherit";
  width: number | "inherit";
}

function SvgHost({ svg }: { svg: SVGSVGElement }) {
  return (
    <div
      className="h-full w-full"
      ref={(node) => {
        if (node?.firstElementChild !== svg) {
          node?.replaceChildren(svg);
        }
      }}
    />
  );
}

/**
 * Renders an excalidraw scene as a static svg image. The heavy `exportToSvg`
 * runtime is loaded on demand so documents without drawings never pay for it.
 */
export function ExcalidrawImage({
  appState,
  containerRef,
  elements,
  files,
  height,
  width,
}: ExcalidrawImageProps) {
  const [svg, setSvg] = useState<SVGSVGElement | null>(null);
  const [renderFailed, setRenderFailed] = useState(false);
  const boxRef = useRef<HTMLDivElement | null>(null);
  const hasExplicitDimensions = width !== "inherit" && height !== "inherit";
  const [isDraggingBox, setIsDraggingBox] = useState(false);
  const fillsBox = hasExplicitDimensions || isDraggingBox;

  useEffect(() => {
    const box = boxRef.current;
    if (!box || typeof ResizeObserver === "undefined") {
      return;
    }

    const syncFillMode = () => {
      setIsDraggingBox(box.style.width !== "" && box.style.height !== "");
    };

    const observer = new ResizeObserver(syncFillMode);
    observer.observe(box);
    syncFillMode();
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    let cancelled = false;

    const renderScene = async () => {
      // oxlint-disable-next-line react/todo -- dynamic import() for code-splitting; oxlint HIR cannot lower it (upstream limitation, not a code issue)
      const { exportToSvg } = await import("@excalidraw/excalidraw");
      const nextSvg = await exportToSvg({
        appState,
        elements: [...elements],
        files: files ?? null,
      });

      nextSvg.removeAttribute("width");
      nextSvg.removeAttribute("height");

      if (!cancelled) {
        setRenderFailed(false);
        setSvg(nextSvg);
      }
    };

    void (async () => {
      try {
        await renderScene();
      } catch {
        if (!cancelled) {
          setRenderFailed(true);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [appState, elements, files]);

  useEffect(() => {
    if (!svg) {
      return;
    }

    svg.style.display = "block";
    svg.style.width = "100%";

    if (fillsBox) {
      svg.style.height = "100%";
      svg.setAttribute("preserveAspectRatio", "none");
      return;
    }

    svg.style.height = "auto";
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
  }, [fillsBox, svg]);

  const style: React.CSSProperties = {};
  if (width !== "inherit") {
    style.width = `${width}px`;
  }
  if (height !== "inherit") {
    style.height = `${height}px`;
  }

  return (
    <div
      className="max-w-full"
      ref={(node) => {
        boxRef.current = node;
        if (containerRef && node) {
          containerRef.current = node;
        }
      }}
      style={style}
    >
      {svg ? <SvgHost svg={svg} /> : null}
      {!svg && renderFailed ? (
        <div className="flex min-h-24 min-w-48 items-center justify-center px-4 py-3 text-xs text-muted-foreground">
          Unable to render drawing
        </div>
      ) : null}
    </div>
  );
}

"use client";

import type {
  AppState,
  BinaryFiles,
  ExcalidrawImperativeAPI,
  ExcalidrawProps,
} from "@excalidraw/excalidraw/types";
import { XIcon } from "lucide-react";
import type { ComponentType } from "react";
import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";

import { Button } from "@/components/ui/button";

import type {
  ExcalidrawInitialElements,
  ExcalidrawScene,
  SaveableExcalidrawScene,
} from "./scene";
import { hasExcalidrawContent } from "./scene";

export interface SaveExcalidrawScenePayload {
  appState: Partial<AppState>;
  elements: ExcalidrawInitialElements;
  files: BinaryFiles;
}

interface ExcalidrawEditorDialogProps {
  /** Scene shown when the editor opens. */
  initialScene: ExcalidrawScene;
  onClose: () => void;
  onSave: (payload: SaveExcalidrawScenePayload) => void;
}

const pickPersistedAppState = (appState: AppState): Partial<AppState> => ({
  exportBackground: appState.exportBackground,
  exportScale: appState.exportScale,
  exportWithDarkMode: appState.theme === "dark",
  isBindingEnabled: appState.isBindingEnabled,
  name: appState.name,
  theme: appState.theme,
  viewBackgroundColor: appState.viewBackgroundColor,
  viewModeEnabled: appState.viewModeEnabled,
  zenModeEnabled: appState.zenModeEnabled,
});

const getSceneSignature = (scene: SaveableExcalidrawScene): string => {
  const activeElements: string[] = [];
  for (const element of scene.elements ?? []) {
    if (!element.isDeleted) {
      activeElements.push(
        `${element.id}:${element.version}:${element.versionNonce}`
      );
    }
  }
  const fileKeys = Object.keys(scene.files ?? {}).toSorted();
  return `${activeElements.join(",")}|${fileKeys.join(",")}`;
};

const loadExcalidrawCanvas = async (): Promise<
  ComponentType<ExcalidrawProps>
> => {
  await import("@excalidraw/excalidraw/index.css");
  const module = await import("@excalidraw/excalidraw");
  return module.Excalidraw as unknown as ComponentType<ExcalidrawProps>;
};

/**
 * Full-screen editing surface for a single excalidraw scene. Saving hands the
 * current elements back to the caller; closing discards local edits.
 */
export function ExcalidrawEditorDialog({
  initialScene,
  onClose,
  onSave,
}: ExcalidrawEditorDialogProps) {
  const [api, setApi] = useState<ExcalidrawImperativeAPI | null>(null);
  const [excalidrawCanvas, setExcalidrawCanvas] =
    useState<ComponentType<ExcalidrawProps> | null>(null);
  const [loadFailed, setLoadFailed] = useState(false);
  const [isDiscardConfirmOpen, setIsDiscardConfirmOpen] = useState(false);
  const dialogRef = useRef<HTMLDialogElement | null>(null);
  const initialSignatureRef = useRef<string | null>(null);
  const latestSceneRef = useRef<SaveableExcalidrawScene>({
    elements: initialScene.elements,
    files: initialScene.files ?? {},
  });

  useEffect(() => {
    initialSignatureRef.current = getSceneSignature({
      elements: initialScene.elements,
      files: initialScene.files ?? {},
    });
  }, [initialScene.elements, initialScene.files]);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      try {
        const loadedCanvas = await loadExcalidrawCanvas();
        if (!cancelled) {
          setExcalidrawCanvas(() => loadedCanvas);
        }
      } catch {
        if (!cancelled) {
          setLoadFailed(true);
        }
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    dialogRef.current?.focus();

    if (typeof document === "undefined") {
      return;
    }

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, []);

  if (typeof document === "undefined") {
    return null;
  }

  const hasUnsavedChanges = () => {
    const baseline =
      initialSignatureRef.current ??
      getSceneSignature({
        elements: initialScene.elements,
        files: initialScene.files ?? {},
      });
    const currentSignature = getSceneSignature(latestSceneRef.current);
    if (currentSignature !== baseline) {
      return true;
    }
    return (
      !hasExcalidrawContent(initialScene) &&
      hasExcalidrawContent(latestSceneRef.current)
    );
  };

  const requestClose = () => {
    if (hasUnsavedChanges()) {
      setIsDiscardConfirmOpen(true);
      return;
    }

    onClose();
  };

  const handleSave = () => {
    const appState = api?.getAppState();
    onSave({
      appState: appState ? pickPersistedAppState(appState) : {},
      elements: latestSceneRef.current.elements,
      files: latestSceneRef.current.files ?? {},
    });
  };

  const Canvas = excalidrawCanvas;

  const renderCanvasContent = () => {
    if (loadFailed) {
      return (
        <div className="flex h-full flex-col items-center justify-center gap-3 p-6 text-center">
          <p className="text-sm font-medium text-destructive">
            Failed to load the drawing canvas.
          </p>
          <Button onClick={onClose} size="sm" variant="outline">
            Close
          </Button>
        </div>
      );
    }

    if (Canvas) {
      return (
        <Canvas
          excalidrawAPI={setApi}
          initialData={{
            appState: initialScene.appState ?? {},
            elements: initialScene.elements,
            files: initialScene.files ?? {},
          }}
          onChange={(elements, _appState, files) => {
            latestSceneRef.current = { elements, files };
          }}
        />
      );
    }

    return (
      <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
        Loading drawing canvas…
      </div>
    );
  };

  return createPortal(
    <dialog
      aria-label="Excalidraw drawing editor"
      aria-modal="true"
      className="fixed inset-0 z-50 m-0 flex h-full max-h-none w-full max-w-none flex-col border-0 bg-background p-0 outline-none"
      onKeyDown={(event) => {
        if (event.key !== "Escape") {
          return;
        }

        if (isDiscardConfirmOpen) {
          event.preventDefault();
          event.stopPropagation();
          setIsDiscardConfirmOpen(false);
          return;
        }

        const target = event.target as HTMLElement | null;
        if (target?.closest(".excalidraw")) {
          return;
        }

        event.preventDefault();
        requestClose();
      }}
      open
      ref={dialogRef}
      tabIndex={-1}
    >
      <header className="flex items-center justify-between border-b px-4 py-2">
        <p className="text-sm font-medium">Excalidraw drawing</p>
        <div className="flex items-center gap-2">
          <Button onClick={requestClose} size="sm" variant="ghost">
            Discard
          </Button>
          <Button disabled={loadFailed} onClick={handleSave} size="sm">
            Save &amp; insert
          </Button>
          <Button
            aria-label="Close drawing editor"
            onClick={requestClose}
            size="icon-sm"
            variant="ghost"
          >
            <XIcon aria-hidden />
          </Button>
        </div>
      </header>

      <div className="relative min-h-0 flex-1">
        {renderCanvasContent()}

        {isDiscardConfirmOpen ? (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/80 backdrop-blur-xs">
            <dialog
              aria-label="Discard changes"
              aria-modal="true"
              className="editor-floating editor-floating-padding-lg m-0 max-h-none w-80 max-w-none border-0"
              open
              role="alertdialog"
            >
              <p className="font-medium">Discard changes?</p>
              <p className="mt-1 text-sm text-muted-foreground">
                Your drawing has unsaved edits that will be lost.
              </p>
              <div className="mt-4 flex justify-end gap-2">
                <Button
                  onClick={() => {
                    setIsDiscardConfirmOpen(false);
                  }}
                  size="sm"
                  variant="outline"
                >
                  Keep editing
                </Button>
                <Button
                  onClick={() => {
                    setIsDiscardConfirmOpen(false);
                    onClose();
                  }}
                  size="sm"
                  variant="destructive"
                >
                  Discard
                </Button>
              </div>
            </dialog>
          </div>
        ) : null}
      </div>
    </dialog>,
    document.body
  );
}

"use client";

import { $isCodeNode } from "@lexical/code";
import { $findMatchingParent, $insertNodeToNearestRoot } from "@lexical/utils";
import {
  $createParagraphNode,
  $getSelection,
  $isRangeSelection,
} from "lexical";
import type { LexicalEditor } from "lexical";

import { $createExcalidrawNode } from "../../core/nodes/excalidraw/node";
import { parseExcalidrawClipboard, serializeExcalidrawScene } from "./scene";

/**
 * Inserts an excalidraw block carrying `data` and re-anchors the selection on
 * a trailing paragraph so the update never commits with a dangling selection.
 * Must run inside `editor.update()`.
 */
export const $insertExcalidrawBlock = (data: string): void => {
  const excalidrawNode = $createExcalidrawNode({ data });
  $insertNodeToNearestRoot(excalidrawNode);

  const paragraph = $createParagraphNode();
  excalidrawNode.insertAfter(paragraph);
  paragraph.select();
};

/**
 * Handles a paste whose `text/plain` payload is an excalidraw clipboard
 * (`{"type":"excalidraw/clipboard","elements":[…]}`). Copying a drawing from
 * an excalidraw canvas writes that JSON to the system clipboard; without this
 * handler the editor dumps the raw JSON into the document as plain text.
 *
 * Returns true when the paste was consumed as a drawing (the caller's command
 * handler then stops propagation); false lets regular pastes fall through.
 */
export const handleExcalidrawPaste = (
  editor: LexicalEditor,
  event: ClipboardEvent
): boolean => {
  const selection = $getSelection();
  if (!$isRangeSelection(selection)) {
    return false;
  }

  // Inside a code block, Excalidraw clipboard JSON is plain code text.
  const anchorNode = selection.anchor.getNode();
  if ($isCodeNode(anchorNode) || $findMatchingParent(anchorNode, $isCodeNode)) {
    return false;
  }

  const clipboardText = event.clipboardData?.getData("text/plain");
  if (!clipboardText) {
    return false;
  }

  const scene = parseExcalidrawClipboard(clipboardText);
  if (!scene) {
    return false;
  }

  event.preventDefault();
  editor.update(() => {
    $insertExcalidrawBlock(
      serializeExcalidrawScene(
        scene.elements,
        scene.appState ?? {},
        scene.files ?? {}
      )
    );
  });
  return true;
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { mergeRegister } from "@lexical/utils";
import {
  COMMAND_PRIORITY_EDITOR,
  COMMAND_PRIORITY_HIGH,
  PASTE_COMMAND,
} from "lexical";
import { useEffect } from "react";

import { ExcalidrawNode } from "../../core/nodes/excalidraw/node";
import { INSERT_EXCALIDRAW_COMMAND } from "./commands";
import { $insertExcalidrawBlock, handleExcalidrawPaste } from "./paste";

/**
 * Mounts the excalidraw insert behavior. Dispatching
 * `INSERT_EXCALIDRAW_COMMAND` inserts an empty drawing block whose editing
 * surface opens immediately; slash commands and toolbar inserts share this
 * single path.
 *
 * Pasting a drawing copied from an excalidraw canvas (its clipboard carries
 * `{"type":"excalidraw/clipboard",…}` in `text/plain`) inserts a drawing
 * block instead of dumping the raw JSON into the document as text.
 */
export function ExcalidrawPlugin(): null {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    if (!editor.hasNodes([ExcalidrawNode])) {
      throw new Error(
        "ExcalidrawPlugin: ExcalidrawNode is not registered on the editor"
      );
    }

    return mergeRegister(
      editor.registerCommand(
        INSERT_EXCALIDRAW_COMMAND,
        () => {
          editor.update(() => {
            $insertExcalidrawBlock("[]");
          });
          return true;
        },
        COMMAND_PRIORITY_EDITOR
      ),
      editor.registerCommand(
        PASTE_COMMAND,
        (event: ClipboardEvent | null) => {
          if (!event) {
            return false;
          }
          return handleExcalidrawPaste(editor, event);
        },
        COMMAND_PRIORITY_HIGH
      )
    );
  }, [editor]);

  return null;
}

import type {
  ExcalidrawElement,
  NonDeleted,
} from "@excalidraw/excalidraw/element/types";
import type {
  AppState,
  BinaryFiles,
  ExcalidrawInitialDataState,
} from "@excalidraw/excalidraw/types";

export type ExcalidrawInitialElements = ExcalidrawInitialDataState["elements"];

/**
 * The subset of excalidraw state persisted inside an ExcalidrawNode. Only the
 * pieces needed to re-open and re-render a drawing are kept, mirroring what
 * the Lexical playground stores.
 */
export interface ExcalidrawScene {
  appState?: Partial<AppState>;
  elements: NonDeleted<ExcalidrawElement>[];
  files?: BinaryFiles;
}

/**
 * The live scene handed back by the excalidraw editor while drawing; element
 * lists are readonly and may be absent until the first change.
 */
export interface SaveableExcalidrawScene {
  appState?: Partial<AppState>;
  elements?: ExcalidrawInitialElements;
  files?: BinaryFiles;
}

const EMPTY_SCENE: ExcalidrawScene = { elements: [] };

export const EMPTY_SCENE_JSON = JSON.stringify(EMPTY_SCENE.elements);

/** Marker excalidraw writes into the clipboard `text/plain` payload on copy. */
export const EXCALIDRAW_CLIPBOARD_TYPE = "excalidraw/clipboard";

interface ExcalidrawClipboardPayload {
  appState?: Partial<AppState>;
  elements?: ExcalidrawInitialElements;
  files?: BinaryFiles;
  type?: string;
}

/**
 * Recognizes excalidraw's own clipboard JSON (`{"type":"excalidraw/clipboard",
 * "elements":[…],"files":{…}}`). Without this, pasting a drawing copied from
 * the canvas dumps the raw JSON into the document as plain text. Returns the
 * scene when the payload is excalidraw clipboard data with at least one
 * element, otherwise null so regular pastes fall through untouched.
 */
export const parseExcalidrawClipboard = (
  text: string
): ExcalidrawScene | null => {
  if (!text.includes(EXCALIDRAW_CLIPBOARD_TYPE)) {
    return null;
  }

  try {
    const parsed: unknown = JSON.parse(text);
    if (typeof parsed !== "object" || parsed === null) {
      return null;
    }

    const payload = parsed as ExcalidrawClipboardPayload;
    if (
      payload.type !== EXCALIDRAW_CLIPBOARD_TYPE ||
      !Array.isArray(payload.elements) ||
      payload.elements.length === 0
    ) {
      return null;
    }

    return {
      appState: payload.appState,
      elements: payload.elements,
      files: payload.files ?? {},
    };
  } catch {
    return null;
  }
};

export const serializeExcalidrawScene = (
  elements: ExcalidrawInitialElements,
  appState: Partial<AppState>,
  files: BinaryFiles
): string => JSON.stringify({ appState, elements, files });
export const parseExcalidrawScene = (data: string): ExcalidrawScene => {
  try {
    const parsed: unknown = JSON.parse(data);
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      !Array.isArray((parsed as ExcalidrawScene).elements)
    ) {
      return EMPTY_SCENE;
    }

    const scene = parsed as ExcalidrawScene;
    return {
      appState: scene.appState,
      elements: scene.elements,
      files: scene.files ?? {},
    };
  } catch {
    return EMPTY_SCENE;
  }
};

export const hasExcalidrawContent = (
  scene: ExcalidrawScene | SaveableExcalidrawScene
): boolean => {
  const elements = scene.elements ?? [];
  return (
    elements.some((element) => !element.isDeleted) ||
    Object.keys(scene.files ?? {}).length > 0
  );
};
